insert into public.properties (id,name,location,description,price,visible,sort_order,photos) values ('la-1','BLAGO home LA 1','Эйлат','Квартира с отдельным входом и собственным двором. Оборудованная кухня, посуда, стиральная машина и интернет. Условия размещения и количество спальных мест уточняются перед заселением.','Условия по запросу',true,1,'[{"src": "assets/1000022379.jpg", "top": -55.78, "mobileTop": -55.78}, {"src": "assets/1000022380.jpg", "top": -94.45, "mobileTop": -94.45}]'::jsonb) on conflict (id) do nothing;
insert into public.properties (id,name,location,description,price,visible,sort_order,photos) values ('la-2','BLAGO home LA 2','Эйлат','Квартира с отдельным входом и собственным двором. Есть кухня, посуда, стиральная машина и интернет. Возможность размещения команды обсуждается с учётом срока и состава группы.','Условия по запросу',true,2,'[{"src": "assets/1000022383.jpg", "top": -65.06, "mobileTop": -65.06}, {"src": "assets/1000022381.jpg", "top": -55.78, "mobileTop": -55.78}]'::jsonb) on conflict (id) do nothing;
insert into public.properties (id,name,location,description,price,visible,sort_order,photos) values ('la-3','BLAGO home LA 3','Эйлат','Квартира для проживания в Эйлате. Отдельный вход, свой двор, кухня с посудой, стиральная машина и интернет. Стоимость и вместимость согласовываются индивидуально.','Условия по запросу',true,3,'[{"src": "assets/1000022385.jpg", "top": -55.78, "mobileTop": -55.78}]'::jsonb) on conflict (id) do nothing;
insert into public.properties (id,name,location,description,price,visible,sort_order,photos) values ('la-4','BLAGO home LA 4','Эйлат','Квартира с отдельным входом и двором. Предусмотрены кухня, посуда, стиральная машина и интернет. Доступность и условия долгосрочного проживания уточняются для вашей команды.','Условия по запросу',true,4,'[{"src": "assets/1000022389.jpg", "top": -178.33, "mobileTop": -178.33}]'::jsonb) on conflict (id) do nothing;
